import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"Runtime Semantics: Public Evidence Pack for Three Articles","description":"","frontmatter":{"title":"Runtime Semantics: Public Evidence Pack for Three Articles","date":"2026-08-27"},"headers":[],"relativePath":"en/research/evidence/2026-08-27-runtime-semantics-evidence-pack.md","filePath":"en/research/evidence/2026-08-27-runtime-semantics-evidence-pack.md","lastUpdated":1787846046000}'),n={name:"en/research/evidence/2026-08-27-runtime-semantics-evidence-pack.md"};function o(r,e,d,l,c,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="runtime-semantics-public-evidence-pack-for-three-articles" tabindex="-1">Runtime Semantics: Public Evidence Pack for Three Articles <a class="header-anchor" href="#runtime-semantics-public-evidence-pack-for-three-articles" aria-label="Permalink to &quot;Runtime Semantics: Public Evidence Pack for Three Articles&quot;">​</a></h1><p>Status: <strong>Published</strong>. This page accompanies the three Runtime-semantics articles dated 2026-08-27. The material is deidentified and inspectable. R1 includes a Windows-specific public probe plus a recorded deidentified result; R2 and R3 include network-free public Readers and checks.</p><p>The purpose is not to certify the whole system. It is to let readers inspect the samples, rules, expected outputs, and non-generalization boundaries behind the published claims.</p><h2 id="_1-what-the-pack-contains" tabindex="-1">1. What the pack contains <a class="header-anchor" href="#_1-what-the-pack-contains" aria-label="Permalink to &quot;1. What the pack contains&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Article</th><th>Public material</th><th>What it can answer</th><th>What it cannot answer</th></tr></thead><tbody><tr><td>Agent cancellation / child-process article</td><td>Public two-level Windows Node process-tree probe, deidentified recorded result, result-check</td><td>Whether <code>taskkill /T /F</code> on one observed Windows host made both a wrapper and one direct child disappear in that sample; readers can also rerun the same contract on their own Windows host</td><td>Arbitrary-depth trees, escaped descendants, privilege boundaries, containers, or remote workers</td></tr><tr><td>Review / REPORT association article</td><td>10 deidentified REPORT association records, public Reader, check script</td><td>How explicit task keys classify the sample as <code>linked / missing / conflict</code></td><td>Failure rate, report truthfulness, business acceptance, or current product quality</td></tr><tr><td>Green-status / UI projection article</td><td>5 deidentified Session observations, public Reader, check script, projection counterexample matrix</td><td>Whether the five disclosed observation semantics can be independently reproduced and which UI facts must remain orthogonal</td><td>Certification of all desktop, PWA, viewer-authority, and end-to-end delivery paths</td></tr></tbody></table><p>This pack does not publish task bodies, agent content, prompts, absolute paths, usernames, real Session IDs, credentials, or user project files.</p><hr><h2 id="_2-r1-windows-cancellation-and-stop-evidence" tabindex="-1">2. R1 | Windows cancellation and stop evidence <a class="header-anchor" href="#_2-r1-windows-cancellation-and-stop-evidence" aria-label="Permalink to &quot;2. R1 | Windows cancellation and stop evidence&quot;">​</a></h2><p>This section supports the agent-cancellation / child-process article.</p><h3 id="experiment-contract" tabindex="-1">Experiment contract <a class="header-anchor" href="#experiment-contract" aria-label="Permalink to &quot;Experiment contract&quot;">​</a></h3><p>A wrapper process starts one long-lived direct child in a fresh temporary directory. After both PIDs are observed, the experiment runs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>taskkill /PID &lt;wrapper&gt; /T /F</span></span></code></pre></div><p>and checks within three seconds whether the wrapper and direct child remain observable.</p><p>The recorded controlled-host result is:</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>wrapper and direct child observable before termination</td><td>yes</td></tr><tr><td><code>taskkill /T /F</code> exit code</td><td><code>0</code></td></tr><tr><td>wrapper exit observed</td><td>yes</td></tr><tr><td>direct child exit observed</td><td>yes</td></tr><tr><td>result</td><td><code>PASS</code></td></tr><tr><td><code>kernel_containment_proven</code></td><td><code>false</code></td></tr></tbody></table><p>Public artifacts:</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-tree-probe.mjs">2026-08-27-r1-windows-taskkill-tree-probe.mjs</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result.json">2026-08-27-r1-windows-taskkill-recorded-result.json</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result-check.mjs">2026-08-27-r1-windows-taskkill-recorded-result-check.mjs</a></li></ul><p>The deidentified recorded result explicitly preserves the claim boundary:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;windows_taskkill_tree_probe_only&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;wrapper_exit_observed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;child_exit_observed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;termination_exit_code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kernel_containment_proven&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="two-checks-must-not-be-confused" tabindex="-1">Two checks must not be confused <a class="header-anchor" href="#two-checks-must-not-be-confused" aria-label="Permalink to &quot;Two checks must not be confused&quot;">​</a></h3><p>To validate the published record itself:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-recorded-result-check.mjs</span></span></code></pre></div><p>Expected output:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fixture&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deidentified_windows_taskkill_tree_probe_result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kernel_containment_proven&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>That checks the structure and claim boundary of the published record. It does not rerun the operating-system experiment.</p><p>To rerun the <code>taskkill /T /F</code> experiment, use <strong>Windows</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-tree-probe.mjs</span></span></code></pre></div><p>The probe creates a temporary wrapper plus direct child, waits until both are observable, invokes <code>taskkill /T /F</code>, and then checks the two PIDs separately. On non-Windows systems it refuses to run instead of reporting a false PASS.</p><p>Even another PASS establishes only that the two known PIDs in this public contract were observed to exit. It does not prove that the execution tree was a kernel-bounded closed set. Escaped children, transient intermediates that create grandchildren, deeper descendants, different privileges, containers, and remote workers require separate counterexamples.</p><hr><h2 id="_3-r2-explicit-report-to-task-association" tabindex="-1">3. R2 | Explicit REPORT-to-TASK association <a class="header-anchor" href="#_3-r2-explicit-report-to-task-association" aria-label="Permalink to &quot;3. R2 | Explicit REPORT-to-TASK association&quot;">​</a></h2><p>Public artifacts:</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-report-association-fixture.json">2026-08-27-r2-report-association-fixture.json</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader.mjs">2026-08-27-r2-association-reader.mjs</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader-check.mjs">2026-08-27-r2-association-reader-check.mjs</a></li></ul><h3 id="classification-rule" tabindex="-1">Classification rule <a class="header-anchor" href="#classification-rule" aria-label="Permalink to &quot;Classification rule&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>action.task_id and ledger.task_id both exist and match  → linked</span></span>
<span class="line"><span>action.task_id is absent                               → missing</span></span>
<span class="line"><span>both exist but disagree                                → conflict</span></span></code></pre></div><p>Filename similarity, nearby timestamps, role, model inference, and &quot;choose the newest record&quot; are not allowed to create the relationship.</p><p>The 10-record fixture produces <code>linked = 4</code>, <code>missing = 4</code>, and <code>conflict = 2</code>.</p><p>The fixture was deidentified from fixed first-party historical records while preserving task-key equality, absence, and disagreement. The original JSONL SHA-256 values are:</p><ul><li><code>47dda7d8cd18b2a11241854823964d9e0a67298535de06e04f2acb807459ac11</code></li><li><code>45cd1d3b4ffc088574d08df48de3ad5db6fd5a99b288005c7a048f2a7355342b</code></li></ul><p>Run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r2-association-reader-check.mjs</span></span></code></pre></div><p>Expected output:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fixture&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deidentified_historical_association&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;counts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;linked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;missing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;conflict&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The public Reader exists to reproduce the disclosed rule over the disclosed fixture; it is not a simulator for the complete Runtime.</p><hr><h2 id="_4-r3-ui-status-projection-five-facts-must-not-collapse-into-one-green-state" tabindex="-1">4. R3 | UI status projection: five facts must not collapse into one green state <a class="header-anchor" href="#_4-r3-ui-status-projection-five-facts-must-not-collapse-into-one-green-state" aria-label="Permalink to &quot;4. R3 | UI status projection: five facts must not collapse into one green state&quot;">​</a></h2><p>This section supports the article <em>What Does a Green Agent Status Actually Mean?</em></p><p>The first-party source path distinguishes five mutually exclusive Session observations. One targeted source test contains <strong>five classification assertions</strong>. Earlier shorthand of &quot;1/1&quot; referred to one passing test case; it should not be read as one tested status or as an end-to-end UI regression.</p><h3 id="disclosed-classification-contract" tabindex="-1">Disclosed classification contract <a class="header-anchor" href="#disclosed-classification-contract" aria-label="Permalink to &quot;Disclosed classification contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Observation</th><th>Output</th><th>The UI must not promote it into</th></tr></thead><tbody><tr><td>Session <code>running</code> + live + progress</td><td><code>executing_with_progress</code></td><td>delivered</td></tr><tr><td>Session <code>running</code> + live + no fine-grained progress</td><td><code>executing_without_fine_progress</code></td><td>failed</td></tr><tr><td>Session <code>running</code> + not live</td><td><code>session_without_live_execution</code></td><td>actively progressing</td></tr><tr><td>Session <code>completed</code> + formal REPORT not yet written</td><td><code>completed_waiting_report</code></td><td>accepted delivery</td></tr><tr><td>Session <code>failed</code> / <code>session_lost</code></td><td><code>technical_error</code></td><td>business rejection</td></tr></tbody></table><h3 id="public-deidentified-reproducer" tabindex="-1">Public deidentified reproducer <a class="header-anchor" href="#public-deidentified-reproducer" aria-label="Permalink to &quot;Public deidentified reproducer&quot;">​</a></h3><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-fixture.json">2026-08-27-r3-ui-status-projection-fixture.json</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-reader.mjs">2026-08-27-r3-ui-status-projection-reader.mjs</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r3-ui-status-projection-check.mjs">2026-08-27-r3-ui-status-projection-check.mjs</a></li></ul><p>The fixture contains five deidentified inputs, one for each disclosed class. The public Reader reproduces the disclosed decision order. The check script verifies <code>actual === expected</code> for all five records and also checks per-class counts.</p><p>Run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r3-ui-status-projection-check.mjs</span></span></code></pre></div><p>Expected output:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fixture&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deidentified_runtime_session_observation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;assertions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The distinction is important: <strong>the public Reader is an independent reproducer of the disclosed contract, not the private production source. Five public assertions do not certify every desktop, PWA, authorization-filter, or end-to-end delivery path.</strong></p><h3 id="projection-counterexample-matrix" tabindex="-1">Projection counterexample matrix <a class="header-anchor" href="#projection-counterexample-matrix" aria-label="Permalink to &quot;Projection counterexample matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Combination</th><th>Acceptable projection</th></tr></thead><tbody><tr><td>viewer is not owner, but may read and a fresh local session exists</td><td>show actual execution from the canonical source; do not hide it merely because the viewer is not owner</td></tr><tr><td>Gateway online, managed-job heartbeat stale</td><td>show connectivity and job liveness separately; do not translate online into executing</td></tr><tr><td>workflow <code>done</code>, evidence association conflicted</td><td>preserve both <code>done</code> and evidence conflict</td></tr><tr><td>runtime / disk / context identity disagree</td><td>publish <code>projection_conflict</code> / unknown, not online</td></tr></tbody></table><p>These combinations test orthogonality: viewer authority, connectivity, Session liveness, progress, REPORT arrival, and lifecycle answer different questions.</p><hr><h2 id="_5-independent-checks" tabindex="-1">5. Independent checks <a class="header-anchor" href="#_5-independent-checks" aria-label="Permalink to &quot;5. Independent checks&quot;">​</a></h2><p>None of the public checks needs access to the private repository. The real R1 probe requires Windows; the R1 record-check, R2, and R3 require only Node.</p><p>R1 published-record check:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-recorded-result-check.mjs</span></span></code></pre></div><p>R1 Windows rerun:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r1-windows-taskkill-tree-probe.mjs</span></span></code></pre></div><p>R2:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r2-association-reader-check.mjs</span></span></code></pre></div><p>R3:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node 2026-08-27-r3-ui-status-projection-check.mjs</span></span></code></pre></div><p>A reviewer should confirm that:</p><ol><li>R1 <code>PASS</code> is not expanded into arbitrary process-tree containment;</li><li>the R1 public probe and recorded result are different evidence objects: one can rerun the experiment, the other preserves a prior host observation;</li><li>R2 deidentification preserves equality, absence, and conflict relations;</li><li>R3&#39;s five public assertions are not expanded into complete UI / PWA certification;</li><li><code>technical_error</code> is not rewritten as business failure, and <code>completed_waiting_report</code> is not rewritten as formal acceptance;</li><li>cancellation request, command exit code, PID disappearance, Gateway, Session, progress, REPORT, lifecycle, and evidence association do not sign for one another.</li></ol><h2 id="_6-overall-evidence-boundary" tabindex="-1">6. Overall evidence boundary <a class="header-anchor" href="#_6-overall-evidence-boundary" aria-label="Permalink to &quot;6. Overall evidence boundary&quot;">​</a></h2><p>This pack is a collection of <strong>reviewable engineering slices</strong>, not product certification and not a large-sample statistical benchmark.</p><ul><li>R1: one prior Windows-host two-level sample plus a public same-contract probe;</li><li>R2: 10 deidentified historical association records;</li><li>R3: 5 semantic classification inputs plus a projection counterexample matrix.</li></ul><p>All conclusions in the three articles must therefore remain scoped to the corresponding samples, rules, versions, and public artifacts. The value of the pack is not to make the system appear all-green. It is to make three categories visible: <strong>what was observed, what can be rerun, and what remains unproven.</strong></p>`,78)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
